from flask import Flask, jsonify
import requests
app = Flask(__name__)

HTML = """<!DOCTYPE html><html dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shaam V16.1 WORLD LITE 🌍</title><style>body{background:#000;color:#fff;font-family:Arial;margin:0}.header{background:#FFD700;color:#000;padding:10px;text-align:center;font-weight:900}.nav{display:flex;gap:4px;padding:5px;background:#111;overflow-x:auto}.nav button{background:#222;color:#fff;border:none;padding:8px 10px;border-radius:20px;font-size:10px}.nav button.active{background:#FFD700;color:#000;font-weight:900}.card{background:#111;border:1px solid #333;border-radius:12px;margin:7px;padding:10px;font-size:12px}.money{background:#111;border:1px solid #FFD700;padding:7px;border-radius:20px;margin:5px;text-align:center;font-size:11px;display:flex;justify-content:space-around}</style></head><body><div class="header">🌍 Shaam V16.1 WORLD LITE - كل الدوريات حقيقية ✅</div><div class="money"><span>🔴 <span id="liveC">0</span> مباشر</span><span>📅 <span id="upC">0</span> قادمة</span><span>🌍 <span id="natC">0</span> منتخبات</span></div><div class="nav"><button class="active" onclick="showTab('live',this)">🔴 مباشر</button><button onclick="showTab('up',this)">📅 القادمة</button><button onclick="showTab('nat',this)">🌍 منتخبات</button></div><div id="live" class="tab"><div id="liveBox" style="text-align:center;padding:15px">⏳ مباشر...</div></div><div id="up" class="tab" style="display:none"><div id="upBox" style="text-align:center;padding:15px">⏳ القادمة...</div></div><div id="nat" class="tab" style="display:none"><div id="natBox" style="text-align:center;padding:15px">⏳ منتخبات...</div></div><script>const LEAGUES=["eng.1","esp.1","ita.1","ger.1","fra.1","tur.1","sau.1","uefa.champions","uefa.europa"];const NAT=["fifa.friendly","uefa.nations","fifa.world.qual"];async function showTab(t,el){document.querySelectorAll('.tab').forEach(x=>x.style.display='none');document.getElementById(t).style.display='block';document.querySelectorAll('.nav button').forEach(b=>b.classList.remove('active'));el.classList.add('active');if(t=='up')loadUp();if(t=='nat')loadNat();}async function fetchLeague(lg){try{let r=await fetch(`https://site.api.espn.com/apis/site/v2/sports/soccer/${lg}/scoreboard`);let d=await r.json();return d.events||[];}catch(e){return[]}}async function load(){let box=document.getElementById('liveBox');let all=[];for(let lg of LEAGUES){let evs=await fetchLeague(lg);evs.forEach(ev=>{let comp=ev.competitions[0];if(comp.status.type.state!='in')return;all.push({home:comp.competitors[0].team.displayName,away:comp.competitors[1].team.displayName,score:`${comp.competitors[0].score||0}-${comp.competitors[1].score||0}`,lg});});}document.getElementById('liveC').innerText=all.length;box.innerHTML=all.length==0?'📭 لا يوجد مباشر الآن - أوروبا تلعب 19:00-23:00 بتوقيت إسطنبول<br><br>جرب تبويب القادمة':all.map(m=>`<div class=card>🔴 <b>${m.home} vs ${m.away}</b> <b style=color:#FFD700>${m.score}</b><br><small>${m.lg} ✅ حقيقي</small></div>`).join('');}async function loadUp(){let box=document.getElementById('upBox');let all=[];let tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);let dateStr=tomorrow.toISOString().slice(0,10).replace(/-/g,'');for(let lg of LEAGUES.slice(0,6)){try{let r=await fetch(`https://site.api.espn.com/apis/site/v2/sports/soccer/${lg}/scoreboard?dates=${dateStr}`);let d=await r.json();(d.events||[]).forEach(ev=>{let comp=ev.competitions[0];all.push({home:comp.competitors[0].team.displayName,away:comp.competitors[1].team.displayName,lg});});}catch(e){}}document.getElementById('upC').innerText=all.length;box.innerHTML=all.length==0?'📭 لا يوجد مباريات بكرا - جرب بعد بكرا':all.map(m=>`<div class=card>📅 <b>${m.home} vs ${m.away}</b><br><small>${m.lg} بكرا ✅ حقيقي</small></div>`).join('');}async function loadNat(){let box=document.getElementById('natBox');let all=[];for(let lg of NAT){let evs=await fetchLeague(lg);evs.forEach(ev=>{let comp=ev.competitions[0];all.push({home:comp.competitors[0].team.displayName,away:comp.competitors[1].team.displayName,lg:lg,state:comp.status.type.state});});}document.getElementById('natC').innerText=all.length;box.innerHTML=all.length==0?'📭 لا يوجد منتخبات الآن - فترة التوقف الدولي خلصت':all.map(m=>`<div class=card style="border-right:4px solid #00bfff">🌍 <b>${m.home} vs ${m.away}</b><br><small>${m.lg} ${m.state}</small></div>`).join('');}load();</script></body></html>"""

@app.route('/')
def home(): return HTML

@app.route('/api/ping')
def ping(): return jsonify({"status":"ok V16.1 LITE"})

if __name__=='__main__':
    app.run(host='0.0.0.0',port=10000)
